class Opt:
    def __init__(self, name, arg=None): self.name=name; self.option_arg=arg
    def get_name(self): return self.name
    def get_arg(self): return self.option_arg
class CmdInv:
    def __init__(self, fol, ops): self.flag_option_list=fol; self.operand_list=ops
def parse(table, args):
    flags={s:e[0] for e in table["flag"] for s in (e if isinstance(e,list) else [e])}
    opts={}
    for e in table["option"]:
        for s in e[:-1]: opts[s]=e[0]
    fol=[]; i=0
    while i<len(args):
        a=args[i]
        if a in flags: fol.append(Opt(flags[a]))
        elif a in opts: fol.append(Opt(opts[a], args[i+1])); i+=1
        elif len(a)>2 and a[0]=='-' and a[1]!='-' and all(('-'+c) in flags for c in a[1:]):
            fol += [Opt(flags['-'+c]) for c in a[1:]]
        else: break
        i+=1
    return CmdInv(fol, args[i:])
class Base:
    def __init__(self, cmd_inv): self.cmd_inv=cmd_inv
    def does_flag_option_list_contain_at_least_one_of(self, names): return any(o.name in names for o in self.cmd_inv.flag_option_list)
    def get_flag_option_list_filtered_with(self, names): return [o for o in self.cmd_inv.flag_option_list if o.name in names]
    def get_operand_list_length(self): return len(self.cmd_inv.operand_list)
    def get_first_operand_name_as_string(self): return self.cmd_inv.operand_list[0]
class InputOutputInfoGeneratorInterface(Base):
    def __init__(self, cmd_inv):
        super().__init__(cmd_inv); self.stdin=False; self.stdout=False
        self.operand_roles=["STREAM_INPUT"]*len(cmd_inv.operand_list)
    def set_implicit_use_of_stdin(self): self.stdin=True
    def set_implicit_use_of_stdout(self): self.stdout=True
    def all_operands_are_streaming_inputs(self): self.operand_roles=["STREAM_INPUT"]*len(self.operand_roles)
    def all_but_first_operand_is_streaming_input(self):
        assert len(self.operand_roles)>=1
        self.operand_roles[1:]=["STREAM_INPUT"]*(len(self.operand_roles)-1)
    def set_first_operand_as_config_arg_type_string(self):
        assert len(self.operand_roles)>=1; self.operand_roles[0]="CONFIG_STRING"
EOF
